// Scans the Deals Tracker for rows the team has marked Closed Won in the Build or Deep Assessment
// pipeline, and skips any deal already processed -- tracked via n8n's own workflow static data,
// keyed by deal_id, so a row sitting at 'Closed Won' for weeks never re-drafts the same case study
// on every subsequent daily run.
const row = $json;
const CASE_STUDY_PIPELINES = ['Build', 'Deep Assessment'];
const dealId = String(row.deal_id || '');

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedDealIds) staticData.processedDealIds = {};
const alreadyProcessed = !!staticData.processedDealIds[dealId];

const isClosedWonCaseStudyDeal = row.stage === 'Closed Won' && CASE_STUDY_PIPELINES.includes(row.pipeline) && !!dealId;
const isNew = isClosedWonCaseStudyDeal && !alreadyProcessed;

if (isNew) {
  staticData.processedDealIds[dealId] = true;
}

return { json: {
  deal_id: dealId,
  client_name: row.client_name || 'Unknown client',
  contact_name: row.contact_name || 'there',
  contact_email: row.contact_email || '',
  is_new_closed_won_deal: isNew,
} };

// Matches every newly-closed deal against the results tracker by deal_id. Runs once for the whole
// batch (not once per item) because it needs both lists -- the deals that just closed AND every
// tracker row -- at the same time, and produces one output item per deal so this handles any number
// of deals closing on the same day correctly, not just one at a time. If nobody's entered the
// before/after numbers yet for a deal, that's a normal state, not an error -- handled explicitly
// rather than crashing on missing data.
const deals = $('Filter Newly Closed Deals').all().map(i => i.json);
const rows = $input.all().map(i => i.json);

function parseMetric(v) {
  // A blank/missing cell means 'not entered yet' -- but a literal 0 is a real, meaningful value
  // (e.g. 'saved 0 hours'), so it must NOT collapse to null too.
  return (v === undefined || v === null || v === '') ? null : Number(v);
}

return deals.map(deal => {
  const match = rows.find(r => String(r.deal_id) === deal.deal_id);
  if (!match) {
    return { json: { deal_id: deal.deal_id, client_name: deal.client_name, contact_name: deal.contact_name, contact_email: deal.contact_email, is_found: false } };
  }
  return { json: {
    deal_id: deal.deal_id,
    client_name: match.client_name || deal.client_name,
    contact_name: deal.contact_name,
    contact_email: deal.contact_email,
    response_time_before_hours: parseMetric(match.response_time_before_hours),
    response_time_after_hours: parseMetric(match.response_time_after_hours),
    no_show_rate_before_pct: parseMetric(match.no_show_rate_before_pct),
    no_show_rate_after_pct: parseMetric(match.no_show_rate_after_pct),
    hours_saved_per_week: parseMetric(match.hours_saved_per_week),
    is_found: true,
  } };
});

const d = $json;
return { json: {
  recipient: $vars.INTERNAL_REVIEWER_EMAIL,
  subject: `Case study ready to draft, but metrics are missing — ${d.client_name}`,
  message: `${d.client_name}'s deal (${d.deal_id}) just closed won, but there's no row yet in the Results Tracker sheet — add response time, no-show rate, and hours-saved before/after numbers, then this will draft automatically on the next run.`,
} };

// Picks whichever of the three metrics improved the most, in percentage terms, as the headline
// stat -- guards against divide-by-zero on any 'before' value that's zero or missing.
const d = $json;
function pctImprovement(before, after, lowerIsBetter) {
  if (before === null || after === null || !before) return null;
  const raw = lowerIsBetter ? (before - after) / before : (after - before) / before;
  return Math.round(raw * 1000) / 10; // one decimal place
}
const responseTimeImprovementPct = pctImprovement(d.response_time_before_hours, d.response_time_after_hours, true);
const noShowImprovementPct = pctImprovement(d.no_show_rate_before_pct, d.no_show_rate_after_pct, true);

const candidates = [];
if (responseTimeImprovementPct !== null) candidates.push({ label: `${responseTimeImprovementPct}% faster response time`, value: responseTimeImprovementPct });
if (noShowImprovementPct !== null) candidates.push({ label: `${noShowImprovementPct}% fewer no-shows`, value: noShowImprovementPct });
if (d.hours_saved_per_week !== null) candidates.push({ label: `${d.hours_saved_per_week} hours saved per week`, value: d.hours_saved_per_week });
candidates.sort((a, b) => b.value - a.value);
const headlineStat = candidates.length ? candidates[0].label : 'measurable operational improvement';

return { json: {
  ...d,
  response_time_improvement_pct: responseTimeImprovementPct,
  no_show_improvement_pct: noShowImprovementPct,
  headline_stat: headlineStat,
} };

// Assembles the draft one-pager copy -- headline plus a plain bullet list of every metric that was
// actually entered. This is Protomated's own marketing copy about its own operational results, not
// legal work of any kind -- but it's still a DRAFT: nothing here gets published without both the internal reviewer's
// review and the client's own sign-off and quote.
const d = $json;
const bullets = [];
if (d.response_time_improvement_pct !== null) bullets.push(`Response time improved ${d.response_time_improvement_pct}% (${d.response_time_before_hours}h → ${d.response_time_after_hours}h)`);
if (d.no_show_improvement_pct !== null) bullets.push(`No-show rate improved ${d.no_show_improvement_pct}% (${d.no_show_rate_before_pct}% → ${d.no_show_rate_after_pct}%)`);
if (d.hours_saved_per_week !== null) bullets.push(`${d.hours_saved_per_week} hours saved per week`);

const draftSummary = `${d.client_name} — ${d.headline_stat}\n\n` + bullets.map(b => `• ${b}`).join('\n');

return { json: { ...d, draft_summary: draftSummary } };

const d = $json;
return { json: {
  ...d,
  recipient: $vars.INTERNAL_REVIEWER_EMAIL,
  subject: `Case study draft ready for review — ${d.client_name}`,
  message: `Draft case study for ${d.client_name} is ready in the Case Studies sheet (row logged just now). Headline: ${d.headline_stat}.\n\n${d.draft_summary}\n\nPolish the copy, then reach out to the client for their sign-off and a quote — a request has also been sent to them separately.`,
} };

const d = $json;
return { json: {
  ...d,
  channel: 'email',
  recipient: d.contact_email,
  subject: `Quick favor — a case study about your results with us`,
  message: `Hi ${d.contact_name}, we'd love to share a short results summary about working together (${d.headline_stat}) as a case study. Nothing gets published without your sign-off — we'll follow up with a draft and would appreciate a quote if you're open to it.`,
} };

// Anchors created_at at noon UTC before day-difference math to avoid the off-by-one-day bug that
// hits servers running west of UTC (same fix used for date math throughout this catalog). Reminds
// once a day once a draft is stale -- no cooldown needed here, since 'still pending' after the first
// reminder should keep nudging daily until it's actually resolved.
const row = $json;
const STALE_REVIEW_DAYS = Number($vars.STALE_REVIEW_DAYS || 5);

const createdStr = row.created_at.includes('T') ? row.created_at : row.created_at + 'T12:00:00Z';
const created = new Date(createdStr);
created.setHours(0, 0, 0, 0);
const today = new Date();
today.setHours(0, 0, 0, 0);
const msPerDay = 24 * 60 * 60 * 1000;
const daysPending = Math.round((today - created) / msPerDay);

return { json: {
  ...row,
  days_pending: daysPending,
  needs_reminder: daysPending >= STALE_REVIEW_DAYS,
} };

const row = $json;
return { json: {
  recipient: $vars.INTERNAL_REVIEWER_EMAIL,
  subject: `Still pending review: ${row.client_name}'s case study (${row.days_pending} days)`,
  message: `${row.client_name}'s case study draft (headline: ${row.headline_stat}) has been sitting in 'pending review' for ${row.days_pending} days. Open the Case Studies sheet to review and move it forward.`,
} };
